select s.*, x.web_event_event_time, x.web_event_duration_sec from sessions s left join lateral (select c.event_time as web_event_event_time, c.duration_sec as web_event_duration_sec from web_events c where c.session_id = s.id and c.event_time <= s.started_at order by c.event_time desc, c.id desc limit 1) x on true
